        let code = "mod serde {\n    pub(crate) trait Trait {}\n}\nimpl serde::Trait for Bank {}\n";
        let paths = impl_trait_paths(code).expect("the fixture parses");
        assert_eq!(paths.len(), 1, "{paths:?}");
